function makeHeritagePlace(p) {
  const destination = p.nameEn + ", " + p.village + ", Surajpur District, Chhattisgarh, India";
  const query = encodeURIComponent(destination);
  return {
    slug: p.slug,
    name: { en: p.nameEn, hi: p.nameHi },
    description: { en: p.descriptionEn, hi: p.descriptionHi },
    overview: { en: p.overviewEn || p.descriptionEn, hi: p.overviewHi || p.descriptionHi },
    history: { en: p.historyEn, hi: p.historyHi },
    storyTitle: { en: p.storyTitleEn || "The story of this place", hi: p.storyTitleHi || "इस स्थान की कहानी" },
    story: { en: p.storyEn, hi: p.storyHi },
    visitorTips: { en: p.tipsEn || safeTips.en, hi: p.tipsHi || safeTips.hi },
    heroImage: p.heroImage || "https://images.unsplash.com/photo-1470240731273-7821a6eeb6bd?auto=format&fit=crop&w=1600&q=85",
    mapUrl: "https://www.google.com/maps/search/?api=1&query=" + query,
    mapEmbedUrl: "https://www.google.com/maps?q=" + query + "&output=embed",
    destination,
    railway: commonRailway,
    sources: [divisionTourismSource, districtTourismSource, ...(p.extraSource ? [p.extraSource] : [])],
    icon: p.icon || "landmark", active: true, sortOrder: p.sortOrder, contentVerified: false
  };
}
